// Convert all properties to boolean

type Flags<T> = {

  [K in keyof T]: boolean;

};

interface User {

  id: number;

  name: string;

  email: string;

}

type UserFlags = Flags<User>;

// Equivalent to:

// {

//   id: boolean;

//   name: boolean;

//   email: boolean;

// }

sections.content:
Mapped types allow you to create new types by transforming properties of existing types.

Basic Mapped Type
Transform every property of an object type into a new type using a single template.

Example

// Convert all properties to boolean

type Flags<T> = {

  [K in keyof T]: boolean;

};

interface User {

  id: number;

  name: string;

  email: string;

}

type UserFlags = Flags<User>;

// Equivalent to:

// {

//   id: boolean;

//   name: boolean;

//   email: boolean;

// }

Try it Yourself »

Mapped Type Modifiers
Add or remove property modifiers like readonly and ? across all keys.

Example

// Make all properties optional

interface Todo {

  title: string;

  description: string;

  completed: boolean;

}

type OptionalTodo = {

  [K in keyof Todo]?: Todo[K];

};

// Remove 'readonly' and '?' modifiers

type Concrete<T> = {

  -readonly [K in keyof T]-?: T[K];

};

// Add 'readonly' and 'required' to all properties

type ReadonlyRequired<T> = {

  +readonly [K in keyof T]-?: T[K];

};

Try it Yourself »

Key Remapping
Rename or filter keys while mapping using as, string helpers, and conditional checks.

Example

// Add prefix to all property names

type Getters<T> = {

  [K in keyof T as `get${Capitalize<string & K>}`]: () => T[K];

};

type UserGetters = Getters<User>;

// {

//   getId: () => number;

//   getName: () => string;

//   getEmail: () => string;

// }

// Filter out properties

type MethodsOnly<T> = {

  [K in keyof T as T[K] extends Function ? K : never]: T[K];

};

Try it Yourself »

Conditional types allow you to define types that depend on a condition.

Basic Conditional Types
Select between types based on a condition checked at the type level.

Example

type IsString<T> = T extends string ? true : false;

type A = IsString<string>;    // true

type B = IsString<number>;    // false

type C = IsString<'hello'>;    // true

type D = IsString<string | number>; // boolean

// Extract array element type

type ArrayElement<T> = T extends (infer U)[] ? U : never;

type Numbers = ArrayElement<number[]>; // number

Try it Yourself »

Infer Keyword
Capture a part of a type within a conditional type by introducing a new type variable with infer.

Example

// Get return type of a function

type ReturnType<T> = T extends (...args: any[]) => infer R ? R : any;

// Get parameter types as a tuple

type Parameters<T> = T extends (...args: infer P) => any ? P : never;

// Get constructor parameter types

type ConstructorParameters<T extends new (...args: any) => any> =

  T extends new (...args: infer P) => any ? P : never;

// Get instance type from a constructor

type InstanceType<T extends new (...args: any) => any> =

  T extends new (...args: any) => infer R ? R : any;

Try it Yourself »

Distributed Conditional Types
Understand how conditionals distribute over unions versus when they are wrapped to prevent distribution.

Example

// Without distribution

type ToArrayNonDist<T> = T extends any ? T[] : never;

type StrOrNumArr = ToArrayNonDist<string | number>; // (string | number)[]

// With distribution

type ToArray<T> = [T] extends [any] ? T[] : never;

type StrOrNumArr2 = ToArray<string | number>; // string[] | number[]

// Filter out non-string types

type FilterStrings<T> = T extends string ? T : never;

type Letters = FilterStrings<'a' | 'b' | 1 | 2 | 'c'>; // 'a' | 'b' | 'c'

Try it Yourself »

Template literal types allow you to build types using template literal syntax.

Basic Template Literal Types
Constrain strings to specific patterns using template literals and unions.

Example

type Greeting = `Hello, ${string}`;

const validGreeting: Greeting = 'Hello, World!';

const invalidGreeting: Greeting = 'Hi there!'; // Error

// With unions

type Color = 'red' | 'green' | 'blue';

type Size = 'small' | 'medium' | 'large';

type Style = `${Color}-${Size}`;

// 'red-small' | 'red-medium' | 'red-large' |

// 'green-small' | 'green-medium' | 'green-large' |

// 'blue-small' | 'blue-medium' | 'blue-large'

Try it Yourself »

String Manipulation Types
Apply built-in helpers to transform string literal types (uppercasing, capitalizing, etc.).

Example

// Built-in string manipulation types

type T1 = Uppercase<'hello'>;  // 'HELLO'

type T2 = Lowercase<'WORLD'>;  // 'world'

type T3 = Capitalize<'typescript'>;  // 'Typescript'

type T4 = Uncapitalize<'TypeScript'>;  // 'typeScript'

// Create an event handler type

type EventType = 'click' | 'change' | 'keydown';

type EventHandler = `on${Capitalize<EventType>}`;

// 'onClick' | 'onChange' | 'onKeydown'

Try it Yourself »

Advanced Patterns
Compose templates with inference and key remapping to extract metadata and generate APIs.

Example

// Extract route parameters

type ExtractRouteParams<T> =

  T extends `${string}:${infer Param}/${infer Rest}`

    ? { [K in Param | keyof ExtractRouteParams<`${Rest}`>]: string }

    : T extends `${string}:${infer Param}`

    ? { [K in Param]: string }

    : {};

type Params = ExtractRouteParams<'/users/:userId/posts/:postId'>;

// { userId: string; postId: string; }

// Create a type-safe event emitter

type EventMap = {

  click: { x: number; y: number };

  change: string;

  keydown: { key: string; code: number };

};

type EventHandlers = {

  [K in keyof EventMap as `on${Capitalize<K>}`]: (event: EventMap[K]) => void;

};

Try it Yourself »

TypeScript provides several built-in utility types for common type transformations.

Common Utility Types
Use built-ins like Partial, Pick, and Omit for common transformations.

Example

// Basic types

interface User {

  id: number;

  name: string;

  email: string;

  createdAt: Date;

}

// Make all properties optional

type PartialUser = Partial<User>;

// make all properties required

type RequiredUser = Required<PartialUser>;

// make all properties read-only

type ReadonlyUser = Readonly<User>;

// pick specific properties

type UserPreview = Pick<User, 'id' | 'name'>;

// omit specific properties

type UserWithoutEmail = Omit<User, 'email'>;

// extract property types

type UserId = User['id']; // number

type UserKeys = keyof User; // 'id' | 'name' | 'email' | 'createdAt'

Try it Yourself »

Advanced Utility Types
Exclude or extract members from unions and create custom mapped helpers.

Example

// Create a type that excludes null and undefined

type NonNullable<T> = T extends null | undefined ? never : T;

// Exclude types from a union

type Numbers = 1 | 2 | 3 | 'a' | 'b';

type JustNumbers = Exclude<Numbers, string>; // 1 | 2 | 3

// Extract types from a union

type JustStrings = Extract<Numbers, string>; // 'a' | 'b'

// Get the type that is not in the second type

type A = { a: string; b: number; c: boolean };

type B = { a: string; b: number };

type C = Omit<A, keyof B>; // { c: boolean }

// Create a type with all properties as mutable

type Mutable<T> = {

  -readonly [K in keyof T]: T[K];

};

Try it Yourself »

Recursive types are useful for modeling tree-like data structures where a type can reference itself.

Basic Recursive Type
Model self-referential structures like trees and nested JSON.

Example

// Simple binary tree

type BinaryTree<T> = {

  value: T;

  left?: BinaryTree<T>;

  right?: BinaryTree<T>;

};

// JSON-like data structure

type JSONValue =

  | string

  | number

  | boolean

  | null

  | JSONValue[]

  | { [key: string]: JSONValue };

// Nested comments

type Comment = {

  id: number;

  content: string;

  replies: Comment[];

  createdAt: Date;

};

Try it Yourself »

Advanced Recursive Types
Express linked lists, directory trees, and recursive state machines.

Example

// Type for a linked list

type LinkedList<T> = {

  value: T;

  next: LinkedList<T> | null;

};

// Type for a directory structure

type File = {

  type: 'file';

  name: string;

  size: number;

};

type Directory = {

  type: 'directory';

  name: string;

  children: (File | Directory)[];

};

// Type for a state machine

type State = {

  value: string;

  transitions: {

    [event: string]: State;

  };

};

// Type for a recursive function

type RecursiveFunction<T> = (x: T | RecursiveFunction<T>) => void;

Try it Yourself »

code_examples.code:
// Simple type guard with typeof

function formatValue(value: string | number): string {

  if (typeof value === 'string') {

    // TypeScript knows value is string here

    return value.trim().toUpperCase();

  } else {

    // TypeScript knows value is number here

    return value.toFixed(2);

  }

}

// Example usage

const result1 = formatValue('  hello  ');  // "HELLO"

const result2 = formatValue(42.1234);      // "42.12"

sections.content:
The typeof operator is a built-in type guard that checks the type of a primitive value at runtime.

It's particularly useful for narrowing primitive types like strings, numbers, booleans, etc.

Basic Usage
Use typeof checks to narrow primitive unions inside conditional branches.

 Example

// Simple type guard with typeof

function formatValue(value: string | number): string {

  if (typeof value === 'string') {

    // TypeScript knows value is string here

    return value.trim().toUpperCase();

  } else {

    // TypeScript knows value is number here

    return value.toFixed(2);

  }

}

// Example usage

const result1 = formatValue('  hello  ');  // "HELLO"

const result2 = formatValue(42.1234);      // "42.12"

Try it Yourself »

In the above example, TypeScript understands the type of value in different branches of the if statement.

The instanceof operator checks if an object is an instance of a specific class or constructor function.

It's useful for narrowing types with custom classes or built-in objects.

Class-based Type Guarding
Narrow unions of class instances by checking the constructor with instanceof.

 Example

class Bird {

  fly() {

    console.log("Flying...");

   }

}

class Fish {

  swim() {

    console.log("Swimming...");

   }

}

function move(animal: Bird | Fish) {

  if (animal instanceof Bird) {

    // TypeScript knows animal is Bird here

    animal.fly();

  } else {

    // TypeScript knows animal is Fish here

    animal.swim();

  }

}

Try it Yourself »

For more complex type checking, you can create custom type guard functions using type predicates.

These are functions that return a type predicate in the form parameterName is Type.

Type Predicate Functions
Return a predicate like value is Type so TypeScript narrows on the true branch.

 Example

interface Car {

  make: string;

  model: string;

  year: number;

}

interface Motorcycle {

  make: string;

  model: string;

  year: number;

  type: "sport" | "cruiser";

}

// Type predicate function

function isCar(vehicle: Car | Motorcycle): vehicle is Car {

  return (vehicle as Motorcycle).type === undefined;

}

function displayVehicleInfo(vehicle: Car | Motorcycle) {

  console.log(`Make: ${vehicle.make}, Model: ${vehicle.model}, Year: ${vehicle.year}`);

  if (isCar(vehicle)) {

    // TypeScript knows vehicle is Car here

    console.log("This is a car");

  } else {

    // TypeScript knows vehicle is Motorcycle here

    console.log(`This is a ${vehicle.type} motorcycle`);

  }

}

Try it Yourself »

The function signature vehicle is Car is a type predicate that tells TypeScript to narrow the type when the function returns true.

Discriminated unions (also known as tagged unions) use a common property (the discriminant) to distinguish between different object types in a union.

This pattern is particularly powerful when combined with type guards.

Basic Discriminated Union
Use a shared literal property (like kind) to switch and narrow to the exact variant.

 Example

interface Circle {

  kind: "circle";

  radius: number;

}

interface Square {

  kind: "square";

  sideLength: number;

}

type Shape = Circle | Square;

function calculateArea(shape: Shape) {

  switch (shape.kind) {

    case "circle":

      // TypeScript knows shape is Circle here

      return Math.PI * shape.radius ** 2;

    case "square":

      // TypeScript knows shape is Square here

      return shape.sideLength ** 2;

  }

}

Try it Yourself »

The kind property is used as a discriminant to determine the type of the shape.

The in operator checks for the existence of a property on an object.

It's particularly useful for narrowing union types where different types have distinct properties.

Property Existence Checking
Narrow union members by testing whether a distinguishing property exists.

 Example

interface Dog {

  bark(): void;

}

interface Cat {

  meow(): void;

}

function makeSound(animal: Dog | Cat) {

  if ("bark" in animal) {

    // TypeScript knows animal is Dog here

    animal.bark();

  } else {

    // TypeScript knows animal is Cat here

    animal.meow();

  }

}

Try it Yourself »

Type assertion functions are a special kind of type guard that can throw an error if the type assertion fails.

They're useful for validating data at runtime.

Assertion Functions
Encode runtime checks that narrow types and throw on invalid input.

 Example

// Type assertion function

function assertIsString(value: unknown): asserts value is string {

  if (typeof value !== 'string') {

    throw new Error('Value is not a string');

  }

}

// Type assertion function with custom error

function assert(condition: unknown, message: string): asserts condition {

  if (!condition) {

    throw new Error(message);

  }

}

// Usage

function processInput(input: unknown) {

  assertIsString(input);

  // input is now typed as string

  console.log(input.toUpperCase());

}

// With custom error

function processNumber(value: unknown): number {

  assert(typeof value === 'number', 'Value must be a number');

  // value is now typed as number

  return value * 2;

}

Try it Yourself »

code_examples.code:
type IsString<T> = T extends string ? true : false;

// Usage examples

type Result1 = IsString<string>; // true

type Result2 = IsString<number>; // false

type Result3 = IsString<"hello">; // true (literal types extend their base types)

// We can use this with variables too

let a: IsString<string>; // a has type 'true'

let b: IsString<number>; // b has type 'false'

sections.content:
Distributive Conditional Types

Conditional types are particularly useful with union types, where they're automatically distributed over union members:

Example

type ToArray<T> = T extends any ? T[] : never;

// When used with a union type, it applies to each member of the union

type StringOrNumberArray = ToArray<string | number>;

// This becomes ToArray<string> | ToArray<number>

// Which becomes string[] | number[]

// We can also extract specific types from a union

type ExtractString<T> = T extends string ? T : never;

type StringsOnly = ExtractString<string | number | boolean | "hello">;

// Result: string | "hello"

Try it Yourself »

Extracting Types from Complex Structures

The infer keyword allows you to declare a type variable within the condition part of a conditional type and then use it in the true branch of the condition:

Example

// Extract the return type of a function type

type ReturnType<T> = T extends (...args: any[]) => infer R ? R : never;

// Examples

function greet() { return "Hello, world!"; }

function getNumber() { return 42; }

type GreetReturnType = ReturnType<typeof greet>; // string

type NumberReturnType = ReturnType<typeof getNumber>; // number

// Extract element type from array

type ElementType<T> = T extends (infer U)[] ? U : never;

type NumberArrayElement = ElementType<number[]>; // number

type StringArrayElement = ElementType<string[]>; // string

Try it Yourself »

Standard Library Utilities

TypeScript includes several built-in conditional types in its standard library:

Example

// Extract<T, U> - Extracts types from T that are assignable to U

type OnlyStrings = Extract<string | number | boolean, string>; // string

// Exclude<T, U> - Excludes types from T that are assignable to U

type NoStrings = Exclude<string | number | boolean, string>; // number | boolean

// NonNullable<T> - Removes null and undefined from T

type NotNull = NonNullable<string | null | undefined>; // string

// Parameters<T> - Extracts parameter types from a function type

type Params = Parameters<(a: string, b: number) => void>; // [string, number]

// ReturnType<T> - Extracts the return type from a function type

type Return = ReturnType<() => string>; // string

Try it Yourself »

Recursive Conditional Types

Conditional types can be used recursively to create complex type transformations:

Example

// Deeply unwrap Promise types

type UnwrapPromise<T> = T extends Promise<infer U> ? UnwrapPromise<U> : T;

// Examples

type A = UnwrapPromise<Promise<string>>; // string

type B = UnwrapPromise<Promise<Promise<number>>>; // number

type C = UnwrapPromise<boolean>; // boolean

Try it Yourself »

Type-Level If-Else Chains
Chain multiple conditions together for complex type logic:

Example

type TypeName<T> =

  T extends string ? "string" :

  T extends number ? "number" :

  T extends boolean ? "boolean" :

  T extends undefined ? "undefined" :

  T extends Function ? "function" :

  "object";

// Usage

type T0 = TypeName<string>; // "string"

type T1 = TypeName<42>; // "number"

type T2 = TypeName<true>; // "boolean"

type T3 = TypeName<() => void>; // "function"

type T4 = TypeName<Date[]>; // "object"

Try it Yourself »

Conditional types are powerful when creating generic utilities and type-safe libraries:

Example

// A function that returns different types based on input type

function processValue<T>(value: T): T extends string

  ? string

  : T extends number

  ? number

  : T extends boolean

  ? boolean

  : never {

  if (typeof value === "string") {

    return value.toUpperCase() as any; // Type assertion needed due to limitations

  } else if (typeof value === "number") {

    return (value * 2) as any;

  } else if (typeof value === "boolean") {

    return (!value) as any;

  } else {

    throw new Error("Unsupported type");

  }

}

// Usage

const stringResult = processValue("hello"); // Returns "HELLO" (type is string)

const numberResult = processValue(10); // Returns 20 (type is number)

const boolResult = processValue(true); // Returns false (type is boolean)

Try it Yourself »

code_examples.code:
Example

// Small example

type Person = { name: string; age: number };

type PartialPerson = { [P in keyof Person]?: Person[P] };

type ReadonlyPerson = { readonly [P in keyof Person]: Person[P] };

// Define an object type

interface Person {

  name: string;

  age: number;

  email: string;

}

// Create a mapped type that makes all properties optional

type PartialPerson = {

  [P in keyof Person]?: Person[P];

};

// Usage

const partialPerson: PartialPerson = {

  name: "John"

  // age and email are optional

};

// Create a mapped type that makes all properties readonly

type ReadonlyPerson = {

  readonly [P in keyof Person]: Person[P];

};

// Usage

const readonlyPerson: ReadonlyPerson = {

  name: "Alice",

  age: 30,

  email: "alice@example.com"

};

// readonlyPerson.age = 31; // Error: Cannot assign to 'age' because it is a read-only property

sections.content:
Core Syntax

Mapped types use the syntax { [P in K]: T } where:

 P is the property name being iterated

 K is a union of property names to iterate over

 T is the resulting type for each property

Example

// Define an object type

interface Person {

  name: string;

  age: number;

  email: string;

}

// Create a mapped type that makes all properties optional

type PartialPerson = {

  [P in keyof Person]?: Person[P];

};

// Usage

const partialPerson: PartialPerson = {

  name: "John"

  // age and email are optional

};

// Create a mapped type that makes all properties readonly

type ReadonlyPerson = {

  readonly [P in keyof Person]: Person[P];

};

// Usage

const readonlyPerson: ReadonlyPerson = {

  name: "Alice",

  age: 30,

  email: "alice@example.com"

};

// readonlyPerson.age = 31; // Error: Cannot assign to 'age' because it is a read-only property

Try it Yourself »

Standard Library Utilities

TypeScript includes several useful built-in mapped types:

 Partial<T>: make all props optional

 Readonly<T>: make all props readonly

 Pick<T, K>: select a subset of keys

 Omit<T, K>: remove keys

 Record<K, V>: map keys to a value type

Example

interface User {

  id: number;

  name: string;

  email: string;

  isAdmin: boolean;

}

// Partial<T> - Makes all properties optional

type PartialUser = Partial<User>;

// Equivalent to: { id?: number; name?: string; email?: string; isAdmin?: boolean; }

// Required<T> - Makes all properties required

type RequiredUser = Required<Partial<User>>;

// Equivalent to: { id: number; name: string; email: string; isAdmin: boolean; }

// Readonly<T> - Makes all properties readonly

type ReadonlyUser = Readonly<User>;

// Equivalent to: { readonly id: number; readonly name: string; ... }

// Pick<T, K> - Creates a type with a subset of properties from T

type UserCredentials = Pick<User, "email" | "id">;

// Equivalent to: { email: string; id: number; }

// Omit<T, K> - Creates a type by removing specified properties from T

type PublicUser = Omit<User, "id" | "isAdmin">;

// Equivalent to: { name: string; email: string; }

// Record<K, T> - Creates a type with specified keys and value types

type UserRoles = Record<"admin" | "user" | "guest", string>;

// Equivalent to: { admin: string; user: string; guest: string; }

Try it Yourself »

Basic Custom Mappers

You can create your own mapped types to transform types in specific ways:

Example

// Base interface

interface Product {

  id: number;

  name: string;

  price: number;

  inStock: boolean;

}

// Create a mapped type to convert all properties to string type

type StringifyProperties<T> = {

  [P in keyof T]: string;

};

// Usage

type StringProduct = StringifyProperties<Product>;

// Equivalent to: { id: string; name: string; price: string; inStock: string; }

// Create a mapped type that adds validation functions for each property

type Validator<T> = {

  [P in keyof T]: (value: T[P]) => boolean;

};

// Usage

const productValidator: Validator<Product> = {

  id: (id) => id > 0,

  name: (name) => name.length > 0,

  price: (price) => price >= 0,

  inStock: (inStock) => typeof inStock === "boolean"

};

Try it Yourself »

Adding and Removing Modifiers

Mapped types also allow you to add or remove property modifiers like readonly and ? (optional):

Example

// Base interface with some readonly and optional properties

interface Configuration {

  readonly apiKey: string;

  readonly apiUrl: string;

  timeout?: number;

  retries?: number;

}

// Remove readonly modifier from all properties

type Mutable<T> = {

  -readonly [P in keyof T]: T[P];

};

// Usage

type MutableConfig = Mutable<Configuration>;

// Equivalent to: { apiKey: string; apiUrl: string; timeout?: number; retries?: number; }

// Make all optional properties required

type RequiredProps<T> = {

  [P in keyof T]-?: T[P];

};

// Usage

type RequiredConfig = RequiredProps<Configuration>;

// Equivalent to: { readonly apiKey: string; readonly apiUrl: string; timeout: number; retries: number; }

Try it Yourself »

Combining with Conditional Types

Mapped types become even more powerful when combined with conditional types:

Example

// Base interface

interface ApiResponse {

  data: unknown;

  status: number;

  message: string;

  timestamp: number;

}

// Conditional mapped type: Convert each numeric property to a formatted string

type FormattedResponse<T> = {

  [P in keyof T]: T[P] extends number ? string : T[P];

};

// Usage

type FormattedApiResponse = FormattedResponse<ApiResponse>;

// Equivalent to: { data: unknown; status: string; message: string; timestamp: string; }

// Another example: Filter for only string properties

type StringPropsOnly<T> = {

  [P in keyof T as T[P] extends string ? P : never]: T[P];

};

// Usage

type ApiResponseStringProps = StringPropsOnly<ApiResponse>;

// Equivalent to: { message: string; }

Try it Yourself »

code_examples.code:
// TypeScript infers these variable types

let name = "Alice"; // inferred as string

let age = 30; // inferred as number

let isActive = true; // inferred as boolean

let numbers = [1, 2, 3]; // inferred as number[]

let mixed = [1, "two", true]; // inferred as (string | number | boolean)[]

// Using the inferred types

name.toUpperCase(); // Works because name is inferred as string

age.toFixed(2); // Works because age is inferred as number

// name.toFixed(2); // Error: Property 'toFixed' does not exist on type 'string'

sections.content:
TypeScript can infer the return type of a function based on its return statements:

 Example

// Return type is inferred as string

function greet(name: string) {

  return `Hello, ${name}!`;

}

// Return type is inferred as number

function add(a: number, b: number) {

  return a + b;

}

// Return type is inferred as string | number

function getValue(key: string) {

   if (key === "name") {

    return "Alice";

   } else {

    return 42;

   }

}

// Using the inferred return types

let greeting = greet("Bob"); // inferred as string

let sum = add(5, 3); // inferred as number

let value = getValue("age"); // inferred as string | number

Try it Yourself »

TypeScript can infer types based on the context in which expressions occur:

 Example

// The type of the callback parameter is inferred from the array method context

const names = ["Alice", "Bob", "Charlie"];

// Parameter 'name' is inferred as string

names.forEach(name => {

  console.log(name.toUpperCase());

});

// Parameter 'name' is inferred as string, and the return type is inferred as number

const nameLengths = names.map(name => {

  return name.length;

});

// nameLengths is inferred as number[]

// Parameter types in event handlers are also inferred

document.addEventListener("click", event => {

  // 'event' is inferred as MouseEvent

  console.log(event.clientX, event.clientY);

});

Try it Yourself »

When working with object literals, TypeScript infers the types of properties:

 Example

// TypeScript infers the type of this object

const user = {

  id: 1,

  name: "Alice",

  email: "alice@example.com",

  active: true,

  details: {

    age: 30,

    address: {

      city: "New York",

      country: "USA"

    }

  }

};

// Accessing inferred properties

console.log(user.name.toUpperCase());

console.log(user.details.age.toFixed(0));

console.log(user.details.address.city.toLowerCase());

// Type errors would be caught

// console.log(user.age); // Error: Property 'age' does not exist on type '...'

// console.log(user.details.name); // Error: Property 'name' does not exist on type '...'

// console.log(user.details.address.zip); // Error: Property 'zip' does not exist on type '...'

Try it Yourself »

Const Assertions

 Example

// Regular type inference (widens to string)

let name = "Alice";  // type: string

// Const assertion (narrows to literal type)

const nameConst = "Alice" as const;  // type: "Alice"

// With objects

const user = {

  id: 1,

  name: "Alice",

  roles: ["admin", "user"] as const  // readonly tuple

} as const;

// user.name = "Bob";  // Error: Cannot assign to 'name' because it is a read-only property

Try it Yourself »

Type Guards and Control Flow Analysis

 Example

function processValue(value: string | number) {

  // Type is narrowed to string in this block

  if (typeof value === "string") {

    console.log(value.toUpperCase());

  }

  // Type is narrowed to number here

  else {

    console.log(value.toFixed(2));

  }

}

// Discriminated unions

interface Circle { kind: "circle"; radius: number; }

interface Square { kind: "square"; size: number; }

type Shape = Circle | Square;

function area(shape: Shape) {

  // Type is narrowed based on 'kind' property

  switch (shape.kind) {

    case "circle":

      return Math.PI * shape.radius ** 2;

    case "square":

      return shape.size ** 2;

  }

}

Try it Yourself »

Here are some best practices for working with TypeScript's type inference:

 Example

// 1. Let TypeScript infer simple types

let message = "Hello"; // Good: no need for explicit type here

// 2. Provide explicit types for function parameters

function formatName(firstName: string, lastName: string) {

  return `${firstName} ${lastName}`;

}

// 3. Consider adding return type annotations for complex functions

function processData(input: string[]): { count: number; items: string[] } {

  return {

    count: input.length,

    items: input.map(item => item.trim())

  };

}

// 4. Use explicit type annotations for empty arrays or objects

const emptyArray: string[] = []; // Without annotation, inferred as any[]

const configOptions: Record<string, unknown> = {}; // Without annotation, inferred as {}

// 5. Use type assertions when TypeScript cannot infer correctly

const canvas = document.getElementById("main-canvas") as HTMLCanvasElement;

Try it Yourself »

While type inference is powerful, there are situations where explicit type annotations are recommended:

 Recommended for Explicit Types

 Public API Contracts: Function parameters and return types in library code

 Complex Types: When the inferred type is too broad or complex

 Documentation: To make the code more self-documenting

 Type Safety: When you need to enforce specific constraints

 Empty Collections: Empty arrays or objects that will be populated later

Performance Considerations

 Example

// Good: Explicit type for complex return values

function processData(input: string[]): { results: string[]; count: number } {

  return {

    results: input.map(processItem),

    count: input.length

  };

}

// Good: Explicit type for empty arrays

const items: Array<{ id: number; name: string }> = [];

// Good: Explicit type for configuration objects

const config: {

  apiUrl: string;

  retries: number;

  timeout: number;

} = {

  apiUrl: "https://api.example.com",

  retries: 3,

  timeout: 5000

};

