interface User {

  id: number;

  name: string;

  email: string;

}

const userRepo = new DataStorage.InMemoryRepository<User>();

userRepo.add({ id: 1, name: 'John Doe', email: 'john@example.com' });

const allUsers = userRepo.getAll();

